content:
:root {
  --bg-gradient: linear-gradient(135deg, #0f172a 0%, #1e1b4b 50%, #111827 100%);
  --card-bg: rgba(30, 41, 59, 0.75);
  --card-border: rgba(255, 255, 255, 0.08);
  --card-shadow: 0 25px 50px -12px rgba(0, 0, 0, 0.5), 0 0 0 1px rgba(255, 255, 255, 0.05);

  --text-main: #f8fafc;
  --text-muted: #94a3b8;
  --text-dim: #64748b;

  --btn-digit-bg: #334155;
  --btn-digit-hover: #475569;
  --btn-digit-text: #f1f5f9;

  --btn-func-bg: #1e293b;
  --btn-func-hover: #334155;
  --btn-func-text: #38bdf8;

  --btn-op-bg: #f97316;
  --btn-op-hover: #ea580c;
  --btn-op-text: #ffffff;

  --btn-eq-bg: #10b981;
  --btn-eq-hover: #059669;
  --btn-eq-text: #ffffff;

  --font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, "Helvetica Neue", Arial, sans-serif;
  --font-mono: "SF Mono", Monaco, Consolas, "Liberation Mono", "Courier New", monospace;
}

* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
  user-select: none;
  -webkit-user-select: none;
}

body {
  font-family: var(--font-family);
  background: var(--bg-gradient);
  min-height: 100vh;
  display: flex;
  align-items: center;
  justify-content: center;
  color: var(--text-main);
  overflow-x: hidden;
  -webkit-font-smoothing: antialiased;
}

/* アプリ全体ラッパー */
.calculator-app {
  width: 100%;
  min-height: 100vh;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 1rem;
}

/* 電卓本体カード */
.calculator-card {
  position: relative;
  width: 100%;
  max-width: 380px;
  background: var(--card-bg);
  backdrop-filter: blur(20px);
  -webkit-backdrop-filter: blur(20px);
  border-radius: 28px;
  border: 1px solid var(--card-border);
  box-shadow: var(--card-shadow);
  padding: 1.5rem;
  display: flex;
  flex-direction: column;
  gap: 1.25rem;
}

/* ヘッダー */
.calc-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 0 0.25rem;
}

.calc-title {
  font-size: 1rem;
  font-weight: 600;
  letter-spacing: 0.05em;
  color: var(--text-muted);
  text-transform: uppercase;
}

.history-btn {
  background: rgba(255, 255, 255, 0.06);
  border: 1px solid rgba(255, 255, 255, 0.1);
  color: var(--text-muted);
  width: 2.25rem;
  height: 2.25rem;
  border-radius: 50%;
  display: flex;
  align-items: center;
  justify-content: center;
  cursor: pointer;
  transition: all 0.2s ease;
  font-size: 1rem;
}

.history-btn:hover {
  background: rgba(255, 255, 255, 0.15);
  color: var(--text-main);
  transform: translateY(-1px);
}

.history-btn:active {
  transform: translateY(1px);
}

/* ディスプレイエリア */
.display-container {
  background: rgba(15, 23, 42, 0.6);
  border: 1px solid rgba(255, 255, 255, 0.05);
  border-radius: 20px;
  padding: 1.25rem 1.5rem;
  display: flex;
  flex-direction: column;
  justify-content: flex-end;
  align-items: flex-end;
  min-height: 110px;
  word-break: break-all;
  overflow: hidden;
  box-shadow: inset 0 2px 4px rgba(0, 0, 0, 0.3);
}

.display-expression {
  font-family: var(--font-mono);
  font-size: 0.95rem;
  color: var(--text-muted);
  min-height: 1.4rem;
  line-height: 1.4rem;
  text-align: right;
  letter-spacing: 0.02em;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  width: 100%;
}

.display-current {
  font-family: var(--font-mono);
  font-size: 2.5rem;
  font-weight: 700;
  line-height: 1.2;
  color: var(--text-main);
  text-align: right;
  letter-spacing: -0.02em;
  width: 100%;
  transition: font-size 0.15s ease;
}

/* キーパッドグリッド */
.keypad-grid {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 0.75rem;
}

/* 基本ボタン */
.calc-btn {
  appearance: none;
  border: none;
  outline: none;
  border-radius: 18px;
  height: 60px;
  font-size: 1.35rem;
  font-weight: 500;
  cursor: pointer;
  display: flex;
  align-items: center;
  justify-content: center;
  transition: all 0.15s ease-in-out;
  box-shadow: 0 4px 6px -1px rgba(0, 0, 0, 0.2), 0 2px 4px -2px rgba(0, 0, 0, 0.1);
  touch-action: manipulation;
}

.calc-btn:active {
  transform: scale(0.94);
  filter: brightness(0.9);
}

/* 数字ボタン */
.btn-digit {
  background-color: var(--btn-digit-bg);
  color: var(--btn-digit-text);
}

.btn-digit:hover {
  background-color: var(--btn-digit-hover);
}

/* 演算子ボタン */
.btn-operator {
  background-color: var(--btn-op-bg);
  color: var(--btn-op-text);
  font-size: 1.5rem;
  font-weight: 600;
}

.btn-operator:hover {
  background-color: var(--btn-op-hover);
}

.btn-operator.is-active {
  outline: 2px solid #ffffff;
  filter: brightness(1.2);
  box-shadow: 0 0 12px rgba(249, 115, 22, 0.6);
}

/* 機能ボタン (C/AC, ±, %, ⌫) */
.btn-function {
  background-color: var(--btn-func-bg);
  color: var(--btn-func-text);
  font-weight: 600;
}

.btn-function:hover {
  background-color: var(--btn-func-hover);
}

/* イコールボタン */
.btn-equal {
  background-color: var(--btn-eq-bg);
  color: var(--btn-eq-text);
  font-size: 1.6rem;
  font-weight: 600;
}

.btn-equal:hover {
  background-color: var(--btn-eq-hover);
}

/* ゼロボタン (横2スパンなどのレイアウト用) */
.btn-zero {
  grid-column: span 1;
}

/* 履歴モーダル バックドロップ */
.history-modal-backdrop {
  position: fixed;
  inset: 0;
  background-color: rgba(15, 23, 42, 0.7);
  backdrop-filter: blur(8px);
  -webkit-backdrop-filter: blur(8px);
  z-index: 50;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 1rem;
  animation: fadeIn 0.2s ease-out;
}

/* 履歴モーダル本体 */
.history-modal {
  background: #1e293b;
  border: 1px solid rgba(255, 255, 255, 0.1);
  border-radius: 24px;
  width: 100%;
  max-width: 400px;
  max-height: 80vh;
  box-shadow: 0 20px 25px -5px rgba(0, 0, 0, 0.5), 0 8px 10px -6px rgba(0, 0, 0, 0.4);
  display: flex;
  flex-direction: column;
  overflow: hidden;
  animation: scaleUp 0.2s ease-out;
}

.history-modal-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 1.25rem 1.5rem;
  border-bottom: 1px solid rgba(255, 255, 255, 0.08);
}

.history-modal-title {
  font-size: 1.15rem;
  font-weight: 600;
  color: var(--text-main);
}

.history-modal-close {
  background: transparent;
  border: none;
  color: var(--text-muted);
  font-size: 1.5rem;
  cursor: pointer;
  display: flex;
  align-items: center;
  justify-content: center;
  width: 2rem;
  height: 2rem;
  border-radius: 50%;
  transition: all 0.15s ease;
}

.history-modal-close:hover {
  background: rgba(255, 255, 255, 0.1);
  color: var(--text-main);
}

/* 履歴一覧 */
.history-list {
  padding: 1rem;
  overflow-y: auto;
  display: flex;
  flex-direction: column;
  gap: 0.75rem;
  max-height: 50vh;
}

.history-item {
  background: rgba(15, 23, 42, 0.5);
  border: 1px solid rgba(255, 255, 255, 0.05);
  border-radius: 14px;
  padding: 0.85rem 1rem;
  display: flex;
  flex-direction: column;
  align-items: flex-end;
  gap: 0.25rem;
  cursor: pointer;
  transition: all 0.15s ease;
}

.history-item:hover {
  background: rgba(51, 65, 85, 0.6);
  border-color: rgba(56, 189, 248, 0.3);
  transform: translateY(-1px);
}

.history-item:active {
  transform: translateY(0);
}

.history-item-exp {
  font-family: var(--font-mono);
  font-size: 0.85rem;
  color: var(--text-muted);
}

.history-item-res {
  font-family: var(--font-mono);
  font-size: 1.25rem;
  font-weight: 700;
  color: #38bdf8;
}

.history-item-time {
  font-size: 0.75rem;
  color: var(--text-dim);
  align-self: flex-start;
}

/* 履歴が空の場合 */
.history-empty {
  padding: 3rem 1rem;
  text-align: center;
  color: var(--text-dim);
  font-size: 0.95rem;
}

/* 履歴消去ボタン */
.history-clear-btn {
  margin: 0 1rem 1rem 1rem;
  background: rgba(239, 68, 68, 0.15);
  border: 1px solid rgba(239, 68, 68, 0.3);
  color: #f87171;
  padding: 0.75rem;
  border-radius: 12px;
  font-weight: 600;
  font-size: 0.9rem;
  cursor: pointer;
  transition: all 0.15s ease;
}

.history-clear-btn:hover {
  background: rgba(239, 68, 68, 0.25);
  border-color: rgba(239, 68, 68, 0.5);
}

.history-clear-btn:active {
  transform: scale(0.98);
}

/* アニメーション */
@keyframes fadeIn {
  from {
    opacity: 0;
  }
  to {
    opacity: 1;
  }
}

@keyframes scaleUp {
  from {
    opacity: 0;
    transform: scale(0.95);
  }
  to {
    opacity: 1;
    transform: scale(1);
  }
}

/* レスポンシブ調整（小型スマホ対応） */
@media (max-width: 360px) {
  .calculator-app {
    padding: 0.5rem;
  }

  .calculator-card {
    padding: 1.1rem;
    gap: 0.85rem;
    border-radius: 20px;
  }

  .calc-btn {
    height: 52px;
    font-size: 1.2rem;
    border-radius: 14px;
  }

  .display-current {
    font-size: 2rem;
  }

  .keypad-grid {
    gap: 0.5rem;
  }
}

export interface CalcHistoryItem {
  id: string;
  expression: string;
  result: string;
  timestamp: string;
}

export type Operator = '+' | '-' | '×' | '÷';
export type OperatorType = Operator | null;

export interface DisplayProps {
  expression: string;
  currentInput: string;
}

export interface KeypadProps {
  onDigit: (digit: string) => void;
  onOperator: (op: Operator) => void;
  onEqual: () => void;
  onClear: () => void;
  onAllClear: () => void;
  onToggleSign: () => void;
  onPercent: () => void;
  onDecimal: () => void;
  onBackspace: () => void;
  isClearAll: boolean;
  activeOperator?: Operator | null;
}

export interface HistoryModalProps {
  isOpen: boolean;
  onClose: () => void;
  history: CalcHistoryItem[];
  onSelectHistory: (item: CalcHistoryItem) => void;
  onClearHistory: () => void;
}

import { DisplayProps } from '../types';

const Display = ({
  expression = '',
  currentInput = '0',
}: DisplayProps) => {
  // 長い数字の場合のフォントサイズ自動縮小（インラインスタイルで微調整）
  const getFontSize = (text: string) => {
    const len = text.length;
    if (len > 14) return '1.5rem';
    if (len > 10) return '1.85rem';
    if (len > 7) return '2.2rem';
    return '2.5rem';
  };

  return (
    <div className="display-container">
      <div className="display-expression" title={expression}>
        {expression || '\u00A0'}
      </div>
      <div
        className="display-current"
        style={{ fontSize: getFontSize(currentInput) }}
        title={currentInput}
        aria-live="polite"
        role="status"
      >
        {currentInput}
      </div>
    </div>
  );
};

export default Display;

import { KeypadProps, OperatorType } from '../types';

interface ExtendedKeypadProps extends KeypadProps {
  activeOperator?: OperatorType;
}

interface ButtonConfig {
  id: string;
  label: string;
  className: string;
  onClick: () => void;
  ariaLabel?: string;
  operatorValue?: OperatorType;
}

const Keypad = ({
  onDigit,
  onOperator,
  onEqual,
  onClear,
  onAllClear,
  onToggleSign,
  onPercent,
  onDecimal,
  onBackspace,
  isClearAll,
  activeOperator,
}: ExtendedKeypadProps) => {
  const handleClearClick = () => {
    if (isClearAll) {
      onAllClear?.();
    } else {
      onClear?.();
    }
  };

  const buttons: ButtonConfig[] = [
    // 1行目: クリア, 符号切替, パーセント, 割る
    {
      id: 'clear',
      label: isClearAll ? 'AC' : 'C',
      className: 'calc-btn btn-function',
      onClick: handleClearClick,
      ariaLabel: isClearAll ? 'オールクリア' : 'クリア',
    },
    {
      id: 'toggle-sign',
      label: '±',
      className: 'calc-btn btn-function',
      onClick: () => onToggleSign?.(),
      ariaLabel: '正負反転',
    },
    {
      id: 'percent',
      label: '%',
      className: 'calc-btn btn-function',
      onClick: () => onPercent?.(),
      ariaLabel: 'パーセント',
    },
    {
      id: 'divide',
      label: '÷',
      className: 'calc-btn btn-operator',
      onClick: () => onOperator?.('÷'),
      ariaLabel: '割り算',
      operatorValue: '÷',
    },
    // 2行目: 7, 8, 9, 掛ける
    {
      id: '7',
      label: '7',
      className: 'calc-btn btn-digit',
      onClick: () => onDigit?.('7'),
    },
    {
      id: '8',
      label: '8',
      className: 'calc-btn btn-digit',
      onClick: () => onDigit?.('8'),
    },
    {
      id: '9',
      label: '9',
      className: 'calc-btn btn-digit',
      onClick: () => onDigit?.('9'),
    },
    {
      id: 'multiply',
      label: '×',
      className: 'calc-btn btn-operator',
      onClick: () => onOperator?.('×'),
      ariaLabel: '掛け算',
      operatorValue: '×',
    },
    // 3行目: 4, 5, 6, 引く
    {
      id: '4',
      label: '4',
      className: 'calc-btn btn-digit',
      onClick: () => onDigit?.('4'),
    },
    {
      id: '5',
      label: '5',
      className: 'calc-btn btn-digit',
      onClick: () => onDigit?.('5'),
    },
    {
      id: '6',
      label: '6',
      className: 'calc-btn btn-digit',
      onClick: () => onDigit?.('6'),
    },
    {
      id: 'subtract',
      label: '-',
      className: 'calc-btn btn-operator',
      onClick: () => onOperator?.('-'),
      ariaLabel: '引き算',
      operatorValue: '-',
    },
    // 4行目: 1, 2, 3, 足す
    {
      id: '1',
      label: '1',
      className: 'calc-btn btn-digit',
      onClick: () => onDigit?.('1'),
    },
    {
      id: '2',
      label: '2',
      className: 'calc-btn btn-digit',
      onClick: () => onDigit?.('2'),
    },
    {
      id: '3',
      label: '3',
      className: 'calc-btn btn-digit',
      onClick: () => onDigit?.('3'),
    },
    {
      id: 'add',
      label: '+',
      className: 'calc-btn btn-operator',
      onClick: () => onOperator?.('+'),
      ariaLabel: '足し算',
      operatorValue: '+',
    },
    // 5行目: 1文字消去, 0, 小数点, 計算結果
    {
      id: 'backspace',
      label: '⌫',
      className: 'calc-btn btn-function',
      onClick: () => onBackspace?.(),
      ariaLabel: '1文字消去',
    },
    {
      id: '0',
      label: '0',
      className: 'calc-btn btn-digit btn-zero',
      onClick: () => onDigit?.('0'),
    },
    {
      id: 'decimal',
      label: '.',
      className: 'calc-btn btn-digit',
      onClick: () => onDecimal?.(),
      ariaLabel: '小数点',
    },
    {
      id: 'equal',
      label: '=',
      className: 'calc-btn btn-equal',
      onClick: () => onEqual?.(),
      ariaLabel: '計算実行',
    },
  ];

  return (
    <div className="keypad-grid">
      {buttons.map((btn) => {
        const isOpActive = btn.operatorValue && activeOperator === btn.operatorValue;
        const activeClass = isOpActive ? 'active is-active' : '';

        return (
          <button
            key={btn.id}
            type="button"
            className={`${btn.className} ${activeClass}`.trim()}
            onClick={btn.onClick}
            aria-label={btn.ariaLabel}
          >
            {btn.label}
          </button>
        );
      })}
    </div>
  );
};

export default Keypad;

import { useEffect, useRef, useState } from 'react';
import { HistoryModalProps, CalcHistoryItem } from '../types';

interface ExtendedHistoryModalProps extends HistoryModalProps {
  onDeleteHistoryItem?: (id: string) => void;
}

const HistoryModal = ({
  isOpen = false,
  onClose,
  history = [],
  onSelectHistory,
  onClearHistory,
  onDeleteHistoryItem,
}: ExtendedHistoryModalProps) => {
  const [localHistory, setLocalHistory] = useState<CalcHistoryItem[]>(history);
  const closeButtonRef = useRef<HTMLButtonElement>(null);
  const modalRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    setLocalHistory(history);
  }, [history]);

  useEffect(() => {
    if (isOpen) {
      closeButtonRef.current?.focus();
    }
  }, [isOpen]);

  const handleKeyDown = (e: React.KeyboardEvent<HTMLDivElement>) => {
    if (e.key === 'Escape') {
      onClose?.();
      return;
    }

    if (e.key === 'Tab') {
      const focusableElements = modalRef.current?.querySelectorAll<HTMLElement>(
        'button, [href], input, select, textarea, [tabindex]:not([tabindex="-1"])'
      );
      if (!focusableElements || focusableElements.length === 0) return;

      const firstElement = focusableElements[0];
      const lastElement = focusableElements[focusableElements.length - 1];

      if (e.shiftKey) {
        if (document.activeElement === firstElement) {
          e.preventDefault();
          lastElement.focus();
        }
      } else {
        if (document.activeElement === lastElement) {
          e.preventDefault();
          firstElement.focus();
        }
      }
    }
  };

  const handleDeleteItem = (e: React.MouseEvent, id: string) => {
    e.stopPropagation();
    setLocalHistory((prev) => prev.filter((item) => item.id !== id));
    onDeleteHistoryItem?.(id);
  };

  const handleClear = () => {
    setLocalHistory([]);
    onClearHistory?.();
  };

  if (!isOpen) return null;

  return (
    <div
      className="history-modal-backdrop"
      onClick={() => onClose?.()}
      onKeyDown={handleKeyDown}
      role="dialog"
      aria-modal="true"
      aria-labelledby="modal-title"
    >
      <div
        ref={modalRef}
        className="history-modal"
        onClick={(e) => e.stopPropagation()}
      >
        <div className="history-modal-header">
          <div id="modal-title" className="history-modal-title">
            計算履歴
          </div>
          <button
            ref={closeButtonRef}
            type="button"
            className="history-modal-close"
            onClick={() => onClose?.()}
            aria-label="閉じる"
          >
            ×
          </button>
        </div>

        {localHistory.length === 0 ? (
          <div className="history-empty">履歴がありません</div>
        ) : (
          <>
            <div className="history-list">
              {localHistory.map((item) => (
                <div
                  key={item.id}
                  className="history-item"
                  onClick={() => {
                    onSelectHistory?.(item);
                    onClose?.();
                  }}
                  role="button"
                  tabIndex={0}
                  onKeyDown={(e) => {
                    if (e.key === 'Enter' || e.key === ' ') {
                      onSelectHistory?.(item);
                      onClose?.();
                    }
                  }}
                >
                  <div
                    style={{
                      display: 'flex',
                      justifyContent: 'space-between',
                      alignItems: 'center',
                      width: '100%',
                    }}
                  >
                    <span
                      style={{
                        fontSize: '0.75rem',
                        color: 'var(--text-dim)',
                        fontFamily: 'var(--font-mono)',
                      }}
                    >
                      {item.timestamp}
                    </span>
                    <button
                      type="button"
                      onClick={(e) => handleDeleteItem(e, item.id)}
                      title="この履歴を削除"
                      aria-label="この履歴を削除"
                      style={{
                        background: 'transparent',
                        border: 'none',
                        color: 'var(--text-dim)',
                        cursor: 'pointer',
                        fontSize: '1rem',
                        lineHeight: 1,
                        padding: '2px 6px',
                        borderRadius: '4px',
                      }}
                    >
                      ×
                    </button>
                  </div>
                  <div className="history-item-exp">{item.expression}</div>
                  <div className="history-item-res">{item.result}</div>
                </div>
              ))}
            </div>
            <button
              type="button"
              className="history-clear-btn"
              onClick={handleClear}
            >
              履歴をすべて消去
            </button>
          </>
        )}
      </div>
    </div>
  );
};

export default HistoryModal;

import { useState, useEffect, useCallback } from 'react';
import { CalcHistoryItem, OperatorType } from './types';
import Display from './components/Display';
import Keypad from './components/Keypad';
import HistoryModal from './components/HistoryModal';

const INITIAL_HISTORY: CalcHistoryItem[] = [
  {
    id: 'init-1',
    expression: '1250 × 8 =',
    result: '10000',
    timestamp: '初期履歴',
  },
  {
    id: 'init-2',
    expression: '150 + 280 =',
    result: '430',
    timestamp: '初期履歴',
  },
];

const App = () => {
  const [currentInput, setCurrentInput] = useState<string>('0');
  const [previousInput, setPreviousInput] = useState<string | null>(null);
  const [operator, setOperator] = useState<OperatorType>(null);
  const [expression, setExpression] = useState<string>('');
  const [waitingForOperand, setWaitingForOperand] = useState<boolean>(false);
  const [history, setHistory] = useState<CalcHistoryItem[]>(INITIAL_HISTORY);
  const [isHistoryOpen, setIsHistoryOpen] = useState<boolean>(false);
  const [hasCalculated, setHasCalculated] = useState<boolean>(false);

  // 四則計算の実行と丸め処理
  const calculate = useCallback(
    (firstNum: number, secondNum: number, op: OperatorType): string => {
      let result = 0;
      switch (op) {
        case '+':
          result = firstNum + secondNum;
          break;
        case '-':
          result = firstNum - secondNum;
          break;
        case '×':
          result = firstNum * secondNum;
          break;
        case '÷':
          if (secondNum === 0) {
            return 'エラー';
          }
          result = firstNum / secondNum;
          break;
        default:
          return String(secondNum);
      }
      // 浮動小数点数誤差対策（最大10桁で丸め）
      const rounded = Math.round(result * 1e10) / 1e10;
      return String(rounded);
    },
    []
  );

  // 数字入力
  const handleDigit = useCallback(
    (digit: string) => {
      if (currentInput === 'エラー') {
        setCurrentInput(digit);
        setWaitingForOperand(false);
        setHasCalculated(false);
        return;
      }

      if (waitingForOperand || hasCalculated) {
        setCurrentInput(digit);
        setWaitingForOperand(false);
        setHasCalculated(false);
      } else {
        if (currentInput === '0') {
          setCurrentInput(digit);
        } else {
          // 入力桁数制限（最大16桁）
          if (currentInput.replace(/[-.]/g, '').length < 16) {
            setCurrentInput((prev) => prev + digit);
          }
        }
      }
    },
    [currentInput, waitingForOperand, hasCalculated]
  );

  // 小数点入力
  const handleDecimal = useCallback(() => {
    if (currentInput === 'エラー' || hasCalculated) {
      setCurrentInput('0.');
      setWaitingForOperand(false);
      setHasCalculated(false);
      return;
    }

    if (waitingForOperand) {
      setCurrentInput('0.');
      setWaitingForOperand(false);
    } else if (!currentInput.includes('.')) {
      setCurrentInput((prev) => prev + '.');
    }
  }, [currentInput, waitingForOperand, hasCalculated]);

  // 演算子入力
  const handleOperator = useCallback(
    (nextOp: OperatorType) => {
      if (currentInput === 'エラー') return;

      const inputValue = parseFloat(currentInput);

      if (operator && waitingForOperand) {
        setOperator(nextOp);
        if (previousInput !== null) {
          setExpression(`${previousInput} ${nextOp}`);
        }
        return;
      }

      if (previousInput === null) {
        setPreviousInput(currentInput);
        setExpression(`${currentInput} ${nextOp}`);
      } else if (operator) {
        const prevValue = parseFloat(previousInput);
        const result = calculate(prevValue, inputValue, operator);

        if (result === 'エラー') {
          setCurrentInput('エラー');
          setPreviousInput(null);
          setOperator(null);
          setExpression('');
          setWaitingForOperand(false);
          return;
        }

        setCurrentInput(result);
        setPreviousInput(result);
        setExpression(`${result} ${nextOp}`);
      }

      setWaitingForOperand(true);
      setOperator(nextOp);
      setHasCalculated(false);
    },
    [currentInput, previousInput, operator, waitingForOperand, calculate]
  );

  // イコール計算実行
  const handleEqual = useCallback(() => {
    if (currentInput === 'エラー' || operator === null || previousInput === null) {
      return;
    }

    const prevValue = parseFloat(previousInput);
    const currentValue = parseFloat(currentInput);
    const result = calculate(prevValue, currentValue, operator);
    const fullExp = `${previousInput} ${operator} ${currentInput} =`;

    if (result !== 'エラー') {
      const newItem: CalcHistoryItem = {
        id: crypto.randomUUID(),
        expression: fullExp,
        result: result,
        timestamp: new Date().toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' }),
      };
      setHistory((prev) => [newItem, ...prev]);
    }

    setCurrentInput(result);
    setExpression(fullExp);
    setPreviousInput(null);
    setOperator(null);
    setWaitingForOperand(false);
    setHasCalculated(true);
  }, [currentInput, operator, previousInput, calculate]);

  // C (現在値クリア)
  const handleClear = useCallback(() => {
    setCurrentInput('0');
  }, []);

  // AC (オールクリア)
  const handleAllClear = useCallback(() => {
    setCurrentInput('0');
    setPreviousInput(null);
    setOperator(null);
    setExpression('');
    setWaitingForOperand(false);
    setHasCalculated(false);
  }, []);

  // 正負反転 (±)
  const handleToggleSign = useCallback(() => {
    if (currentInput === '0' || currentInput === 'エラー') return;
    setCurrentInput((prev) =>
      prev.startsWith('-') ? prev.slice(1) : '-' + prev
    );
  }, [currentInput]);

  // パーセント (%)
  const handlePercent = useCallback(() => {
    if (currentInput === 'エラー') return;
    const value = parseFloat(currentInput);
    const result = Math.round((value / 100) * 1e10) / 1e10;
    setCurrentInput(String(result));
  }, [currentInput]);

  // 1文字消去 (⌫)
  const handleBackspace = useCallback(() => {
    if (currentInput === 'エラー' || waitingForOperand || hasCalculated) {
      setCurrentInput('0');
      return;
    }

    if (currentInput.length === 1 || (currentInput.length === 2 && currentInput.startsWith('-'))) {
      setCurrentInput('0');
    } else {
      setCurrentInput((prev) => prev.slice(0, -1));
    }
  }, [currentInput, waitingForOperand, hasCalculated]);

  // 履歴項目の再利用
  const handleSelectHistory = useCallback((item: CalcHistoryItem) => {
    setCurrentInput(item.result);
    setPreviousInput(null);
    setOperator(null);
    setExpression(`履歴: ${item.expression}`);
    setWaitingForOperand(false);
    setHasCalculated(true);
  }, []);

  // 履歴全削除
  const handleClearHistory = useCallback(() => {
    setHistory([]);
  }, []);

  // キーボードショートカット対応
  useEffect(() => {
    const handleKeyDown = (event: KeyboardEvent) => {
      // モーダル表示中はモーダル操作を優先
      if (isHistoryOpen) {
        if (event.key === 'Escape') {
          setIsHistoryOpen(false);
        }
        return;
      }

      const { key } = event;

      if (/^[0-9]$/.test(key)) {
        event.preventDefault();
        handleDigit(key);
      } else if (key === '.') {
        event.preventDefault();
        handleDecimal();
      } else if (key === '+') {
        event.preventDefault();
        handleOperator('+');
      } else if (key === '-') {
        event.preventDefault();
        handleOperator('-');
      } else if (key === '*' || key === 'x' || key === 'X') {
        event.preventDefault();
        handleOperator('×');
      } else if (key === '/') {
        event.preventDefault();
        handleOperator('÷');
      } else if (key === 'Enter' || key === '=') {
        event.preventDefault();
        handleEqual();
      } else if (key === 'Backspace') {
        event.preventDefault();
        handleBackspace();
      } else if (key === 'Escape') {
        event.preventDefault();
        handleAllClear();
      } else if (key === '%') {
        event.preventDefault();
        handlePercent();
      } else if (key === 'h' || key === 'H') {
        event.preventDefault();
        setIsHistoryOpen((prev) => !prev);
      }
    };

    window.addEventListener('keydown', handleKeyDown);
    return () => {
      window.removeEventListener('keydown', handleKeyDown);
    };
  }, [
    isHistoryOpen,
    handleDigit,
    handleDecimal,
    handleOperator,
    handleEqual,
    handleBackspace,
    handleAllClear,
    handlePercent,
  ]);

  // CとACの切り替え判定（入力が0で、式もない場合はAC）
  const isClearAll = currentInput === '0' && previousInput === null && !expression;

  return (
    <div className="calculator-app">
      <div className="calculator-card">
        <header className="calc-header">
          <h1 className="calc-title">電卓</h1>
          <button
            type="button"
            className="history-btn"
            onClick={() => setIsHistoryOpen(true)}
            title="計算履歴を見る (H)"
            aria-label="計算履歴"
          >
            🕒
          </button>
        </header>

        <Display
          expression={expression}
          currentInput={currentInput}
        />

        <Keypad
          onDigit={handleDigit}
          onOperator={handleOperator}
          onEqual={handleEqual}
          onClear={handleClear}
          onAllClear={handleAllClear}
          onToggleSign={handleToggleSign}
          onPercent={handlePercent}
          onDecimal={handleDecimal}
          onBackspace={handleBackspace}
          isClearAll={isClearAll}
          activeOperator={operator}
        />
      </div>

      <HistoryModal
        isOpen={isHistoryOpen}
        onClose={() => setIsHistoryOpen(false)}
        history={history}
        onSelectHistory={handleSelectHistory}
        onClearHistory={handleClearHistory}
      />
    </div>
  );
};

export default App;
